/* @lc app=leetcode id=3816 lang=kotlin */ class Solution { fun lb(a: List<Int>, v: Int): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] < v) m + 1 to hi else lo to m } }.last().first fun lexSmallestAfterDeletion(s: String): String = (0..25).map { c -> s.indices.filter { s[it] - 'a' == c } }.let { ps -> (0..25).map { s.lastIndexOf('a' + it) }.let { last -> (0..25).filter { ps[it].isNotEmpty() }.fold(0) { m, c -> m or (1 shl c) }.let { full -> StringBuilder().let { sb -> generateSequence(0 to full) { (pos, need) -> if (need == 0) null else (0..25).mapNotNull { c -> lb(ps[c], pos).let { i -> if (i < ps[c].size) ps[c][i].let { p -> if ((0..25).all { l -> (need shr l and 1 == 0) || l == c || last[l] > p }) c to p else null } else null } }.minByOrNull { it.first }?.let { (c, p) -> sb.append('a' + c).let { p + 1 to (need and (1 shl c).inv()) } } }.count().let { sb.toString() } } } } } }